\item[$(i)$] $\boldsymbol{M}^{\beta}$ satisfies $\sm$.

\item[$(ii)$] $\boldsymbol{M}^{\beta}$ does not satisfy  $\dc$ (and hence $\mg$ either).

\item[$(iii)$] $\gamma(\boldsymbol{M}^{\beta})=\beta$.
\end{itemize}

